//! Generate the OpenGL bindings and embed the port's icon into the Windows
//! game binary.
//!
//! The icon is the port's own (K1a, a rust black hole, chosen
//! 2026-10-28 so a release ships none of Frontier's artwork): every pixel is
//! generated by a procedural recipe (kept with the artwork sources outside
//! this repository), sizes 256 down to
//! 16 px. Mirrors the V2000 `IDI_ICON1` packaging so the port can sit beside
//! the retail data and start on double-click.

use std::fs::File;
use std::path::PathBuf;
use std::process::Command;

use gl_generator::{Api, Fallbacks, GlobalGenerator, Profile, Registry};

fn main() {
    let out_dir = PathBuf::from(std::env::var("OUT_DIR").unwrap());
    // OpenGL 2.1 with framebuffer objects, as the V2000 port's backend uses:
    // old enough for any desktop driver, and offscreen frames keep the
    // native framebuffer size apart from the window.
    let mut bindings = File::create(out_dir.join("gl_bindings.rs")).expect("create GL bindings");
    Registry::new(
        Api::Gl,
        (2, 1),
        Profile::Compatibility,
        Fallbacks::All,
        ["GL_ARB_framebuffer_object", "GL_EXT_framebuffer_object"],
    )
    .write_bindings(GlobalGenerator, &mut bindings)
    .expect("write GL bindings");

    let manifest_dir = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let icon = manifest_dir.join("assets/infestation.ico");
    println!("cargo:rerun-if-changed={}", icon.display());

    if std::env::var("CARGO_CFG_TARGET_OS").ok().as_deref() != Some("windows") {
        return;
    }
    if !icon.is_file() {
        println!(
            "cargo:warning=missing the port's icon at {}",
            icon.display()
        );
        return;
    }

    let rc_path = out_dir.join("infestation_icon.rc");
    let obj_path = out_dir.join("infestation_icon.o");
    let icon_rc = icon
        .canonicalize()
        .unwrap_or(icon)
        .to_string_lossy()
        .replace('\\', "/");
    std::fs::write(&rc_path, format!("IDI_ICON1 ICON \"{icon_rc}\"\n")).expect("write icon.rc");

    let status = Command::new("windres")
        .args([
            "-O",
            "coff",
            "-i",
            rc_path.to_str().expect("utf-8 rc path"),
            "-o",
            obj_path.to_str().expect("utf-8 obj path"),
        ])
        .status();
    match status {
        Ok(status) if status.success() => {
            println!("cargo:rustc-link-arg-bins={}", obj_path.display());
        }
        Ok(status) => {
            println!("cargo:warning=windres failed ({status}); the game EXE keeps the default icon")
        }
        Err(error) => println!(
            "cargo:warning=windres unavailable ({error}); the game EXE keeps the default icon"
        ),
    }
}
